{ // H1: Placed positive-priority job can be notified and escalated to manager
var manager = new ScheduleManager();
var job = new Job
{
    Id = "job-100",
    Duration = TimeSpan.FromHours(2),
    Priority = 8,
    RequiredSkill = "dispatch"
};
var resource = new Resource
{
    Name = "resource-a",
    Skills = new List<string> { "dispatch" },
    Calendar = new List<Slot>()
};

var placeResult = manager.Place(job, resource);
var placementCount = manager.PlacementCount;
var notifyResult = manager.Notify(job);
var notifiedCount = manager.NotifiedCount;
var escalateResult = manager.Escalate(job);

Check.Equal("resource-a", placeResult);
Check.Equal(1, placementCount);
Check.True(notifyResult);
Check.Equal(1, notifiedCount);
Check.Equal("manager", escalateResult);
}
{ // E1: Place rejects an empty job identifier without storing a placement
var manager = new ScheduleManager();
var job = new Job
{
    Id = "",
    Duration = TimeSpan.FromHours(1),
    Priority = 1,
    RequiredSkill = ""
};
var resource = new Resource
{
    Name = "resource-b",
    Skills = new List<string>(),
    Calendar = new List<Slot>()
};

var result = manager.Place(job, resource);

Check.Equal("no id", result);
Check.Equal(0, manager.PlacementCount);
}
{ // B1: Place observes calendar capacity below at and above fifty
var belowManager = new ScheduleManager();
var belowJob = new Job { Id = "job-49", Duration = TimeSpan.FromMinutes(30) };
var belowResource = new Resource { Name = "resource-49" };
for (var i = 0; i < 49; i++)
    belowResource.Calendar.Add(new Slot());

var atManager = new ScheduleManager();
var atJob = new Job { Id = "job-50", Duration = TimeSpan.FromMinutes(30) };
var atResource = new Resource { Name = "resource-50" };
for (var i = 0; i < 50; i++)
    atResource.Calendar.Add(new Slot());

var aboveManager = new ScheduleManager();
var aboveJob = new Job { Id = "job-51", Duration = TimeSpan.FromMinutes(30) };
var aboveResource = new Resource { Name = "resource-51" };
for (var i = 0; i < 51; i++)
    aboveResource.Calendar.Add(new Slot());

var belowResult = belowManager.Place(belowJob, belowResource);
var atResult = atManager.Place(atJob, atResource);
var aboveResult = aboveManager.Place(aboveJob, aboveResource);

Check.Equal("resource-49", belowResult);
Check.Equal(1, belowManager.PlacementCount);
Check.Equal("resource-50", atResult);
Check.Equal(1, atManager.PlacementCount);
Check.Equal("resource full", aboveResult);
Check.Equal(0, aboveManager.PlacementCount);
}
{ // A1: Match selects the least loaded resource having the required skill
var manager = new ScheduleManager();
var job = new Job
{
    Id = "job-match",
