    Name = "heavy-match",
    Skills = new List<string> { "welding" }
};
for (var i = 0; i < 3; i++)
    heavyMatch.Calendar.Add(new Slot());
var lightMatch = new Resource
{
    Name = "light-match",
    Skills = new List<string> { "welding" }
};
lightMatch.Calendar.Add(new Slot());
var resources = new List<Resource> { nonMatch, heavyMatch, lightMatch };

var matched = manager.Match(job, resources);

Check.NotNull(matched);
Check.Equal("light-match", matched!.Name);
}
{ // D1: Repeated placement of the same job identifier is rejected
var manager = new ScheduleManager();
var job = new Job
{
    Id = "job-repeat",
    Duration = TimeSpan.FromHours(1),
    Priority = 2,
    RequiredSkill = ""
};
var firstResource = new Resource
{
    Name = "resource-first",
    Skills = new List<string>(),
    Calendar = new List<Slot>()
};
var secondResource = new Resource
{
    Name = "resource-second",
    Skills = new List<string>(),
    Calendar = new List<Slot>()
};

var firstResult = manager.Place(job, firstResource);
var countAfterFirst = manager.PlacementCount;
var secondResult = manager.Place(job, secondResource);
var countAfterSecond = manager.PlacementCount;

Check.Equal("resource-first", firstResult);
Check.Equal(1, countAfterFirst);
Check.Equal("already placed", secondResult);
Check.Equal(1, countAfterSecond);
}

